INSERT INTO `courses` (`id`, `code`, `name`, `level`, `duration`, `eligibility`, `seats`, `fees`, `description`, `status`) VALUES
(1, 'ANM', 'Auxiliary Nursing & Midwifery', 'Diploma in Nursing', '2 Years (4 Semesters)', '10+2 in Arts / Science / Commerce (Min 40-45%, Age 17-35)', '60 Seats', '₹55,000 / Year', 'Fundamental nursing foundation, maternal and child healthcare, community immunization, clinical bedside care, and rural health center postings.', 'Active'),
(2, 'GNM', 'General Nursing and Midwifery', 'Diploma in General Nursing', '3 Years (Incl. 6M Clinical Internship)', '10+2 with English & PCB / Arts / Commerce (Min 40%+)', '60 Seats', '₹75,000 / Year', 'Comprehensive healthcare nursing in medical-surgical wards, pediatric care, obstetrics & gynecology, psychiatric nursing, and community health.', 'Active'),
(3, 'B.Sc Nursing', 'Bachelor of Science in Nursing', 'Undergraduate Degree', '4 Years (8 Semesters)', '10+2 with Physics, Chemistry & Biology (Min 45-50%)', '40 Seats', '₹95,000 / Year', 'Advanced professional nursing degree with intensive clinical rotations, emergency trauma care, critical care ICU nursing, and healthcare administration.', 'Active'),
(4, 'P.B. B.Sc', 'Post Basic B.Sc Nursing', 'Post Basic Degree', '2 Years', 'Passed GNM Nursing & Registered RN/RM with State Nursing Council', '30 Seats', '₹70,000 / Year', 'Designed for registered GNM nurses to advance their clinical expertise into nursing education, administration, and specialized hospital practice.', 'Active'),
(5, 'DMLT', 'Diploma in Medical Laboratory Technology', 'Paramedical Diploma', '2 Years', '10+2 Science (PCB / PCM)', '40 Seats', '₹45,000 / Year', 'Practical clinical training in automated biochemistry, diagnostic hematology, serology, microbiology, and blood banking.', 'Active'),
(6, 'OT Tech', 'Diploma in Operation Theatre Technology', 'Paramedical Diploma', '2 Years', '10+2 Science (PCB/PCM)', '30 Seats', '₹45,000 / Year', 'Surgical room sterilization, surgical instrumentation preparation, anesthesia assisting, and recovery room patient support.', 'Active');
